{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Tenuifolin, a pentacyclic triterpenoid diacid glycoside closely related to the query's scaffold, was detected in mouse brain after oral administration, directly demonstrating that this polar carboxylate-bearing triterpenoid class can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A-VI, a high-molecular-weight triterpenoid saponin, reached 248.7 ng/g in rat brain after systemic exposure, showing meaningful brain penetration despite a large polar surface area.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ginsenosides including triterpenoid acids were detected in brain after oral administration, confirming that triterpenoid carboxylic acids can cross the BBB even when brain concentrations are lower than plasma concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "BA10, a triterpenoid-derived tracer, showed high brain uptake and reversible tracer kinetics in pigs, providing direct in vivo evidence that this scaffold can be CNS-penetrant.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the physicochemical prior predicts poor passive diffusion, direct in vivo evidence from closely related triterpenoid acids and saponins consistently demonstrates brain penetration after systemic or oral administration. The query shares the same pentacyclic triterpenoid scaffold and carboxylic acid functionality, supporting meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma or unbound brain concentration data are available for the exact query molecule.",
    "The succinate ester in the query may be hydrolyzed in vivo, and the resulting metabolite's CNS exposure is not directly measured.",
    "Efflux transporter involvement for the query is inferred but not experimentally confirmed.",
    "Most supportive evidence is qualitative or shows low brain concentrations relative to plasma, so the degree of 'meaningful' exposure is not precisely quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

